(function(root){'use strict';
class HostCommunications{
 constructor(o){Object.assign(this,o);this.device=localStorage.getItem('fz_host_next_device')||HostCore.uid();localStorage.setItem('fz_host_next_device',this.device);this.peers={};this.messages={};this.unsubs=[];this.recorder=null;this.call=null;this.incoming=null;this.lastShout='';}
 watch(ref,fn,event='value'){ref.on(event,fn,e=>this.toast(e.message));this.unsubs.push(()=>ref.off(event,fn));}
 start(){const base=this.connection.ref;this.watch(base.child('reservations'),snap=>{this.reservations=snap.val()||{};this.onReservationsChange?.();this.drawReservations?.();this.reservationAlertCheck();});this.reservationWatching=true;this.reservationAlertTimer=setInterval(()=>this.reservationAlertCheck(),30000);this.presence=base.child('presence/'+this.device);this.presence.onDisconnect().remove();this.publishPresence();this.presenceTimer=setInterval(()=>this.publishPresence(),20000);this.watch(base.child('presence'),s=>this.peers=s.val()||{});this.watch(base.child('messages').orderByKey().limitToLast(80),s=>{this.messages=s.val()||{};this.drawMessages();});this.watch(base.child('inbox/'+this.device),s=>{const v=s.val();if(!v||v.expiresAt<this.connection.now())return;const id=s.key;if(this.call||this.incoming){void base.child('calls/'+id).update({state:'busy'});return;}this.incoming={...v,id};this.incomingDialog();},'child_added');this.watch(base.child('shout'),s=>{const v=s.val();if(!v||v.id===this.lastShout||v.expiresAt<this.connection.now())return;this.lastShout=v.id;const layer=document.createElement('div');layer.className='shout';const text=document.createElement('span');text.textContent=v.text;const button=document.createElement('button');button.textContent='GOT IT';button.onclick=()=>layer.remove();layer.append(text,button);document.body.appendChild(layer);setTimeout(()=>layer.remove(),Math.max(0,v.expiresAt-this.connection.now()));});}
 publishPresence(){if(!this.connection.connected)return;void this.presence.set({role:this.getRole(),online:true,seenAt:this.connection.now(),device:this.device}).catch(()=>{});}
 openChat(){const e=this.escape;this.openDialog('Manager Chat / Voice / Call',`<div class="actions"><button id="recordVN">RECORD VOICE NOTE</button><button id="startAudioCall">AUDIO CALL</button><button id="startVideoCall">VIDEO CALL</button>${this.call?'<button id="resumeCall">OPEN ACTIVE CALL</button>':''}</div><div id="chatMessages" class="chat-list"></div><form id="chatForm" class="chat-input"><input id="chatText" aria-label="Chat message" maxlength="1000" placeholder="Message to the team…" required><button class="primary">SEND</button></form><label for="callTarget">Call recipient · connected devices</label><select id="callTarget" class="field">${Object.values(this.peers).filter(p=>p.device!==this.device&&p.online&&this.connection.now()-p.seenAt<60000).map(p=>`<option value="${e(p.device)}">${e(p.role)} · ${e(p.device.slice(0,6))}</option>`).join('')}</select>`);this.drawMessages();document.getElementById('chatForm').onsubmit=async event=>{event.preventDefault();const input=document.getElementById('chatText'),text=input.value.trim();if(!text)return;try{await this.sendMessage({text});input.value='';}catch(e){this.toast(e.message);}};document.getElementById('recordVN').onclick=()=>this.recordVoice();document.getElementById('startAudioCall').onclick=()=>this.startCall(false);document.getElementById('startVideoCall').onclick=()=>this.startCall(true);if(document.getElementById('resumeCall'))document.getElementById('resumeCall').onclick=()=>this.callDialog();}
 drawMessages(){const box=document.getElementById('chatMessages');if(!box)return;const e=this.escape;box.innerHTML=Object.values(this.messages).sort((a,b)=>a.at-b.at).map(m=>`<div class="message"><small>${e(m.from)} · ${new Date(m.at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</small>${m.voice?`<button data-voice="${e(m.id)}">▶ PLAY VOICE NOTE</button>`:`<p>${e(m.text)}</p>`}</div>`).join('');box.scrollTop=box.scrollHeight;box.querySelectorAll('[data-voice]').forEach(b=>b.onclick=async()=>{try{const s=await this.connection.ref.child('voice/'+b.dataset.voice).get(),v=s.val();if(!v||!/^data:audio\//.test(v.data))throw Error('Voice note is unavailable.');const player=document.createElement('audio');player.controls=true;player.src=v.data;b.replaceWith(player);await player.play();}catch(e){this.toast(e.message);}});}
 async sendMessage(fields,voiceData){if(!this.connection.connected)throw Error('Not connected.');const at=this.connection.now(),id='msg_'+at+'_'+HostCore.uid(),message={id,from:this.getRole(),device:this.device,at,...fields},patch={['messages/'+id]:message};if(voiceData)patch['voice/'+id]={data:voiceData,at};await this.connection.ref.update(patch);this.toast('MESSAGE SENT');const oldest=Object.keys(this.messages).sort().slice(0,-79);if(oldest.length){const cleanup={};oldest.forEach(key=>{cleanup['messages/'+key]=null;cleanup['voice/'+key]=null;});void this.connection.ref.update(cleanup).catch(()=>{});}}
 async recordVoice(){if(this.recorder?.state==='recording'){this.recorder.stop();return;}try{if(!navigator.mediaDevices?.getUserMedia||!root.MediaRecorder)throw Error('Voice recording is not supported in this browser.');const stream=await navigator.mediaDevices.getUserMedia({audio:true}),type=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t)),rec=new MediaRecorder(stream,type?{mimeType:type}:{}),chunks=[];this.recorder=rec;const button=document.getElementById('recordVN');if(button){button.textContent='STOP + SEND VOICE NOTE';button.classList.add('recording');}rec.ondataavailable=event=>{if(event.data.size)chunks.push(event.data);};rec.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());clearTimeout(this.recordTimer);this.recorder=null;if(button){button.textContent='RECORD VOICE NOTE';button.classList.remove('recording');}try{const blob=new Blob(chunks,{type:rec.mimeType||'audio/mp4'});if(blob.size>1500000)throw Error('Voice note is too large. Record a shorter message.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});await this.sendMessage({voice:true},data);}catch(e){this.toast(e.message);}};rec.start();this.recordTimer=setTimeout(()=>{if(rec.state==='recording')rec.stop();},60000);}catch(e){this.toast(e.message);}}
 async buildPeer(video,side,id){if(!navigator.mediaDevices?.getUserMedia||!root.RTCPeerConnection)throw Error('Calls require a browser with camera/microphone support.');const stream=await navigator.mediaDevices.getUserMedia({audio:true,video}),pc=new RTCPeerConnection({iceServers:this.connection.config.rtcIceServers||[{urls:'stun:stun.l.google.com:19302'}]}),session={id,side,video,pc,stream,seen:new Set(),remoteSet:false,settingRemote:false,published:side==='callee',localIce:[]};stream.getTracks().forEach(track=>pc.addTrack(track,stream));pc.onicecandidate=event=>{if(event.candidate){const value=event.candidate.toJSON();if(!session.published)session.localIce.push(value);else void this.connection.ref.child('calls/'+id+'/ice/'+side).push(value).catch(()=>{});}};pc.ontrack=event=>{session.remoteStream=event.streams[0];const remote=document.getElementById('remoteVideo');if(remote){remote.srcObject=session.remoteStream;void remote.play().catch(()=>{});}};pc.onconnectionstatechange=()=>{const el=document.getElementById('callStatus');if(el)el.textContent=pc.connectionState==='connected'?'CALL CONNECTED':pc.connectionState.toUpperCase();if(['failed','closed'].includes(pc.connectionState)&&this.call===session)void this.endCall();};this.call=session;return session;}
 async startCall(video){if(this.call)return this.callDialog();const to=document.getElementById('callTarget')?.value;if(!to)return this.toast('No other connected device is available.');try{const id='call_'+this.connection.now()+'_'+HostCore.uid(),session=await this.buildPeer(video,'caller',id);session.to=to;const offer=await session.pc.createOffer();await session.pc.setLocalDescription(offer);const at=this.connection.now();await this.connection.ref.update({['calls/'+id]:{id,from:this.device,fromRole:this.getRole(),to,video,offer:{type:offer.type,sdp:offer.sdp},state:'ringing',at,expiresAt:at+60000},['inbox/'+to+'/'+id]:{id,from:this.device,fromRole:this.getRole(),video,at,expiresAt:at+60000}});session.published=true;session.localIce.forEach(c=>void this.connection.ref.child('calls/'+id+'/ice/caller').push(c).catch(()=>{}));session.localIce=[];this.listenCall(session);this.callDialog();this.ringTimer=setTimeout(()=>{if(this.call===session&&session.pc.connectionState!=='connected')void this.endCall();},65000);}catch(e){this.toast(e.message);if(this.call)void this.endCall();}}
 incomingDialog(){const c=this.incoming;this.openDialog('Incoming '+(c.video?'Video':'Audio')+' Call',`<h3>${this.escape(c.fromRole)}</h3><p class="helper">A connected team device is calling.</p><div class="actions"><button id="acceptIncoming" class="primary">ANSWER</button><button id="declineIncoming" class="danger">DECLINE</button></div>`);document.getElementById('acceptIncoming').onclick=()=>this.acceptCall();document.getElementById('declineIncoming').onclick=()=>this.declineCall();}
 async acceptCall(){const incoming=this.incoming;if(!incoming)return;try{const raw=(await this.connection.ref.child('calls/'+incoming.id).get()).val();if(!raw||raw.state!=='ringing'||raw.expiresAt<this.connection.now())throw Error('The call has ended.');const session=await this.buildPeer(raw.video,'callee',raw.id);session.to=raw.from;await session.pc.setRemoteDescription(raw.offer);session.remoteSet=true;const answer=await session.pc.createAnswer();await session.pc.setLocalDescription(answer);await this.connection.ref.child('calls/'+raw.id).update({answer:{type:answer.type,sdp:answer.sdp},state:'answered'});await this.connection.ref.child('inbox/'+this.device+'/'+raw.id).remove();this.incoming=null;this.listenCall(session);this.callDialog();}catch(e){this.toast(e.message);if(this.call)void this.endCall();}}
 listenCall(session){const ref=this.connection.ref.child('calls/'+session.id);session.listener=async snap=>{const data=snap.val();if(!data||['ended','declined','busy'].includes(data.state)){if(this.call===session)await this.endCall(false);return;}try{if(session.side==='caller'&&data.answer&&!session.remoteSet&&!session.settingRemote){session.settingRemote=true;await session.pc.setRemoteDescription(data.answer);session.remoteSet=true;session.settingRemote=false;}if(session.remoteSet){const other=session.side==='caller'?'callee':'caller';for(const [key,candidate]of Object.entries(data.ice?.[other]||{}))if(!session.seen.has(key)){session.seen.add(key);await session.pc.addIceCandidate(candidate);}}}catch(e){this.toast('Call connection: '+e.message);}};ref.on('value',session.listener);session.callRef=ref;}
 callDialog(){const s=this.call;if(!s)return;this.openDialog(s.video?'Video Call':'Audio Call','<p id="callStatus">CONNECTING…</p><video id="remoteVideo" autoplay playsinline></video><video id="localVideo" autoplay playsinline muted></video><button id="endCall" class="danger full">END CALL</button>');document.getElementById('localVideo').srcObject=s.stream;if(s.remoteStream)document.getElementById('remoteVideo').srcObject=s.remoteStream;document.getElementById('endCall').onclick=()=>this.endCall();}
 async declineCall(){const c=this.incoming;if(!c)return;await this.connection.ref.child('calls/'+c.id).update({state:'declined'});await this.connection.ref.child('inbox/'+this.device+'/'+c.id).remove();this.incoming=null;this.closeDialog();}
 async endCall(notify=true){const s=this.call;if(!s)return;this.call=null;clearTimeout(this.ringTimer);s.callRef?.off('value',s.listener);s.pc.onconnectionstatechange=null;s.pc.close();s.stream.getTracks().forEach(t=>t.stop());if(notify)try{await this.connection.ref.child('calls/'+s.id).update({state:'ended'});}catch(_){}const patch={['inbox/'+this.device+'/'+s.id]:null};if(s.to)patch['inbox/'+s.to+'/'+s.id]=null;void this.connection.ref.update(patch).catch(()=>{});setTimeout(()=>void this.connection.ref.child('calls/'+s.id).remove().catch(()=>{}),5000);this.closeDialog();this.toast('CALL ENDED');}
 async purgeExpiredReservations(){if(this.purgingReservations)return;this.purgingReservations=true;try{for(const [id,r]of Object.entries(this.reservations||{})){if(!HostCore.reservationUndoExpired(r,this.connection.now()))continue;await this.connection.ref.child('reservations/'+id).transaction(current=>HostCore.reservationUndoExpired(current,this.connection.now())?null:undefined,undefined,false);}}catch(_){}finally{this.purgingReservations=false;}}
 reservationAlertCheck(){void this.purgeExpiredReservations();if(document.getElementById('reservationUndoList'))this.drawReservations?.();if(this.isEntered&&!this.isEntered())return;for(const alert of ReservationFlow.alerts(this.reservations,this.connection.now()))this.showReservationAlert(alert);}
 showReservationAlert(alert){const key='fz_res_flow_'+alert.key;this.shownReservationAlerts??=new Set();if(this.shownReservationAlerts.has(key))return;try{if(localStorage.getItem(key))return;}catch(_){}this.shownReservationAlerts.add(key);let stack=document.getElementById('reservationAlertStack');if(!stack){stack=document.createElement('div');stack.id='reservationAlertStack';stack.className='reservation-alert-stack';document.body.appendChild(stack);}const card=document.createElement('aside');card.className='reservation-flow-alert';card.setAttribute('role','alert');card.innerHTML='<small>'+this.escape(alert.title)+'</small><strong>'+this.escape(alert.name)+'</strong><p>'+Number(alert.people)+' guests · '+this.escape(alert.time)+' · Huntsville<br>'+this.escape(alert.detail)+'</p><div class="actions"><button data-review>VIEW RESERVATION</button><button data-ack>GOT IT</button></div>';const acknowledge=()=>{try{localStorage.setItem(key,'seen');}catch(_){}card.remove();if(!stack.children.length)stack.remove();};card.querySelector('[data-ack]').onclick=acknowledge;card.querySelector('[data-review]').onclick=()=>{acknowledge();this.openReservationDetails(alert.id);};stack.appendChild(card);this.reservationSound?.();if(typeof Notification!=='undefined'&&Notification.permission==='granted')try{new Notification(alert.title,{body:alert.name+' · '+alert.people+' guests · '+alert.time,tag:key,icon:'./icon-192.png'});}catch(_){} }
 async syncReservationSms(id){if(!this.connection.connected||typeof fetch!=='function')return;try{await fetch('https://juicy-huntsville-reservations.hollyfree85.chatgpt.site/api/sms/sync?id='+encodeURIComponent(id),{method:'POST',signal:AbortSignal.timeout(10000)});}catch(_){} }
 async enableReservationAlerts(){if(typeof Notification==='undefined')return this.toast('This browser supports in-app reservation reminders only.');try{const granted=await Notification.requestPermission();this.toast(granted==='granted'?'RESERVATION NOTIFICATIONS ENABLED':'In-app reservation reminders remain active while the app is open.');}catch(e){this.toast(e.message);}}

 reservationStamp(r){return r?JSON.stringify(['date','time','name','people','phone','email','table','note','at','updatedAt','status','deletedAt'].map(k=>r[k]??null)):'';}
 async changeReservation(id,expected,change){let conflict=false;const stamp=this.reservationStamp(expected),at=this.connection.now();const result=await this.connection.ref.child('reservations/'+id).transaction(current=>{if(this.reservationStamp(current)!==stamp){conflict=true;return;}conflict=false;const next=change(current,at);if(current&&next){const edited=['date','time','name','people','phone'].some(k=>current[k]!==next[k]);if(edited||current.status==='deleted'&&next.status!=='deleted'){next.smsRevisionAt=at;delete next.guestReply;}else if(current.guestReply)next.guestReply=current.guestReply;}return next;},undefined,false);if(!result.committed)throw Error(conflict?'Reservation changed on another device. Reopen it and try again.':'Reservation was not saved.');void this.syncReservationSms(id);}
 openReservationUndo(){const e=this.escape;this.openDialog('Undo Deleted Reservations','<p class="helper">Restore complete reservation details, including the phone number, within 3 days (72 hours) after deletion.</p><div id="reservationUndoList"></div><button id="backToReservations" class="full">BACK TO RESERVATIONS</button>');const render=()=>{const box=document.getElementById('reservationUndoList');if(!box)return;const rows=Object.entries(this.reservations||{}).filter(([,r])=>HostCore.reservationUndoAvailable(r,this.connection.now())).sort((a,b)=>(b[1].deletedAt||0)-(a[1].deletedAt||0));box.innerHTML=rows.map(([id,r])=>`<div class="panel-info"><b>${e(r.name)}</b> · ${e(r.date)} · ${e(r.time)} · ${r.people} guests<br>${e(r.phone||r.email||'No contact recorded')}<br><small>Undo expires: ${e(new Date(HostCore.reservationUndoExpiry(r)).toLocaleString('en-US',{timeZone:'America/Chicago'}))} (Huntsville)</small><button class="primary full" data-res-restore="${e(id)}">RESTORE RESERVATION</button></div>`).join('')||'<p>No deleted reservations available to restore. Reservations permanently deleted before this update may not be available.</p>';box.querySelectorAll('[data-res-restore]').forEach(b=>b.onclick=async()=>{const id=b.dataset.resRestore,old=this.reservations[id];if(old?.status!=='deleted')return this.toast('Reservation was already restored or changed.');b.disabled=true;try{await this.changeReservation(id,old,(current,at)=>{if(!HostCore.reservationUndoAvailable(current,this.connection.now()))throw Error('The 72-hour recovery period has expired.');const next={...current,status:current.statusBeforeDelete||'scheduled',updatedAt:at};delete next.deletedAt;delete next.statusBeforeDelete;return next;});this.toast('RESERVATION RESTORED · PHONE RETAINED');render();}catch(error){b.disabled=false;this.toast(error.message);}});};this.drawReservations=render;document.getElementById('backToReservations').onclick=()=>this.openReservations();render();}
 openReservationDetails(id){const r=this.reservations[id];if(!r||r.status==='deleted')return this.toast('Reservation is no longer available.');const e=this.escape,shift=this.getShift?.()||'PM',candidates=ReservationFlow.candidates(this.connection.state,this.connection.config,r,id,shift,this.reservations,this.connection.now());this.openDialog('Reservation Details',`<div class="reservation-detail-card"><h3>${e(r.name)}</h3><p class="reservation-reply-status">${e(ReservationFlow.replyStatus(r))}</p><dl>${[['Date',r.date],['Time',r.time+' · Huntsville'],['Guests',r.people],['Phone',r.phone||'Not provided'],['Email',r.email||'Not provided'],['Table',r.table||'Not assigned'],['Notes',r.note||'—'],...(r.source==='online'?[['Source','Online booking'],['Reference',id.slice(-6).toUpperCase()]]:[])].map(([label,value])=>`<dt>${e(String(label))}</dt><dd>${e(String(value))}</dd>`).join('')}</dl></div><section class="reservation-candidates"><h3>Table candidates · ${e(shift)}</h3><p class="helper">Current Floor snapshot: confirmed capacities, approved table combinations, formation, rotation and server workload. ACCEPT seats the listed guests with this server and updates Board and Floor.</p>${candidates.length?candidates.map((c,index)=>`<article><strong>${e(c.table)} · ${e(c.server)}</strong><p>Section ${e(c.section)} · Beeper ${e(c.beeper)}<br>${c.turns} turns · ${c.activeTables} active tables · ${c.activeGuests} guests → ${c.afterGuests} with this party</p><small>${c.min===c.capacity?c.capacity:c.min+'–'+c.capacity} seats · ${e(c.seatingType)}${c.tables.length>1?' · COMBINE THESE TABLES':''}${c.recent?' · RECENT PARTY — check workload':''}</small><button class="primary party-accept" type="button" data-res-accept="${index}">ACCEPT</button></article>`).join(''):'<p>No eligible READY tables or approved combinations in the same section. Check the Floor and current formation.</p>'}<button id="refreshReservationCandidates" class="full">REFRESH TABLE CANDIDATES</button></section><p class="helper">SMS reminders require a verified, activated sender. A guest reply appears here only after it reaches our system.</p><button id="backToReservations" class="full">BACK TO RESERVATIONS</button>`);const context={state:this.connection.state,config:this.connection.config,shift,reservationId:id,reservationSnapshot:JSON.stringify(r)};document.querySelectorAll('[data-res-accept]').forEach(button=>button.onclick=async()=>{if(this.acceptingRecommendation)return;this.acceptingRecommendation=true;document.querySelectorAll('[data-res-accept]').forEach(b=>b.disabled=true);try{await this.acceptRecommendation(candidates[Number(button.dataset.resAccept)],r.people,context);}catch(error){this.toast(error.message);if(document.getElementById('modal').open&&document.getElementById('modalTitle').textContent==='Reservation Details')this.openReservationDetails(id);}finally{this.acceptingRecommendation=false;}});document.getElementById('refreshReservationCandidates').onclick=()=>this.openReservationDetails(id);document.getElementById('backToReservations').onclick=()=>this.openReservations();}
 openGuestBookingLink(){const url='https://hollyfree85-ai.github.io/FZ-Host-Board/book.html';this.openDialog('Guest Booking Link',`<p class="helper">Share this public link with guests. Reservations for 6 or more go directly into this Board. Guests do not need a login.</p><label for="guestBookingURL">Guest reservation link</label><input id="guestBookingURL" class="field" type="url" readonly value="${url}"><div class="actions"><button id="copyGuestBookingURL" class="primary">COPY LINK</button><a href="${url}" target="_blank" rel="noopener noreferrer" class="guest-booking-open">OPEN GUEST FORM</a></div><p class="helper">Board reminders: 1 hour and 10 minutes before arrival while this app is open.</p><button id="backToReservations" class="full">BACK TO RESERVATIONS</button>`);document.getElementById('copyGuestBookingURL').onclick=async()=>{try{await navigator.clipboard.writeText(url);this.toast('GUEST BOOKING LINK COPIED');}catch{document.getElementById('guestBookingURL').select();this.toast('Select and copy the link above.');}};document.getElementById('backToReservations').onclick=()=>this.openReservations();}
 openReservations(table=''){const e=this.escape;this.openDialog('Reservations',`<div class="reservation-toolbar"><div><label for="resDate">Date</label><input id="resDate" class="field" type="date" value="${this.connection.state.day}"></div><button id="enableReservationAlerts" class="full">ENABLE RESERVATION NOTIFICATIONS</button><p class="helper">Reminders 1 hour and 10 minutes before each reservation while this app is open. Allow notifications for a system alert.</p><button id="guestBookingLink" class="full">GUEST BOOKING LINK</button><button id="undoReservationDelete" class="full">UNDO DELETE · RESERVATIONS</button><button id="reservationsFromDate" class="full">SHOW FROM SELECTED DATE</button><button id="upcomingReservations" class="full">SHOW ALL UPCOMING RESERVATIONS</button></div><div id="reservationList" class="reserved-list"></div><form id="reservationForm"><h3>New Reservation · minimum 6 guests</h3><div class="reservation-form-grid"><div><label for="resName">Guest name</label><input id="resName" class="field" maxlength="100" required></div><div><label for="resTime">Time</label><input id="resTime" type="time" class="field" required></div><div><label for="resPeople">Guests</label><input id="resPeople" type="number" class="field" min="6" max="120" value="6" required></div><div><label for="resPhone">Phone · optional</label><input id="resPhone" type="tel" class="field" maxlength="30"></div><div><label for="resEmail">Email · optional</label><input id="resEmail" type="email" class="field" maxlength="254"></div><div><label for="resTable">Table · optional</label><select id="resTable" class="field"><option value="">Not assigned</option>${this.connection.config.tables.map(t=>`<option value="${e(t.id)}" ${t.id===table?'selected':''}>${e(t.id)}</option>`).join('')}</select></div><div><label for="resNote">Notes · optional</label><input id="resNote" class="field" maxlength="300"></div></div><label class="reservation-consent"><input id="resSmsConsent" type="checkbox"> Guest agreed to reservation texts at this number: 1-hour and 10-minute reminders, CONFIRM / HERE replies. Message/data rates may apply; STOP to opt out.</label><button class="primary full" id="saveReservation">SAVE RESERVATION</button></form>`);let showUpcoming=true,fromDate=false;const render=()=>{const day=document.getElementById('resDate')?.value,box=document.getElementById('reservationList');if(!box)return;const rows=Object.entries(this.reservations||{}).filter(([,r])=>r.status!=='deleted'&&(fromDate?r.date>=day:showUpcoming?r.date>=this.connection.state.day:r.date===day)).sort((a,b)=>(a[1].date+' '+a[1].time).localeCompare(b[1].date+' '+b[1].time));box.innerHTML=rows.length?'<div class="reservation-table-scroll"><table class="reservation-table"><caption>Upcoming Reservations</caption><thead><tr>'+['Date','Time','Guest name','Guests','Phone','Email','Table','Notes','Guest status','Actions'].map(h=>'<th scope="col">'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(([id,r])=>`<tr data-res-row="${e(id)}">${[['date','date'],['time','time'],['name','text'],['people','number'],['phone','tel'],['email','email'],['table','text'],['note','text']].map(([key,type])=>`<td><input aria-label="${e(key)}" data-res-field="${key}" type="${type}" value="${e(String(r[key]??''))}" ${key==='people'?'min="6" max="120"':key==='name'?'maxlength="100"':key==='phone'?'maxlength="30"':key==='email'?'maxlength="254"':key==='note'?'maxlength="300"':''} disabled>${key==='name'&&r.source==='online'?'<small class="online-reservation-label">ONLINE BOOKING</small>':''}</td>`).join('')}<td class="reservation-reply-status">${e(ReservationFlow.replyStatus(r))}</td><td><div class="reservation-row-actions"><button data-res-details="${e(id)}">DETAILS</button><button data-res-edit="${e(id)}">EDIT</button><button data-res-save="${e(id)}" class="primary" disabled>SAVE</button><button data-res-delete="${e(id)}" class="danger">DELETE</button></div></td></tr>`).join('')+'</tbody></table></div>':'<p class="helper">No reservations for this date.</p>';box.querySelectorAll('[data-res-details]').forEach(b=>b.onclick=()=>this.openReservationDetails(b.dataset.resDetails));box.querySelectorAll('[data-res-edit]').forEach(b=>b.onclick=()=>{const row=b.closest('tr');row.querySelectorAll('[data-res-field]').forEach(input=>input.disabled=false);const validate=()=>{const n=Number(row.querySelector('[data-res-field=people]').value);row.querySelector('[data-res-save]').disabled=!Number.isInteger(n)||n<6||n>120;};row.querySelectorAll('[data-res-field]').forEach(input=>input.oninput=validate);validate();row.classList.add('editing');row.querySelector('[data-res-field="name"]').focus();});box.querySelectorAll('[data-res-save]').forEach(b=>b.onclick=async()=>{const row=b.closest('tr'),value={...this.reservations[b.dataset.resSave]};for(const input of row.querySelectorAll('[data-res-field]'))value[input.dataset.resField]=input.dataset.resField==='people'?Number(input.value):input.value.trim();if(!value.date||!value.time||!value.name||!Number.isInteger(value.people)||value.people<6||value.people>120)return this.toast('Complete date, time, name and 6–120 guests.');if(value.table&&!this.connection.config.tables.some(t=>t.id===value.table))return this.toast('Choose a valid table.');b.disabled=true;try{await this.changeReservation(b.dataset.resSave,this.reservations[b.dataset.resSave],(current,at)=>({...current,...value,updatedAt:at}));this.toast('RESERVATION SAVED');render();}catch(error){b.disabled=false;this.toast(error.message);}});box.querySelectorAll('[data-res-delete]').forEach(b=>b.onclick=async()=>{const id=b.dataset.resDelete,old=this.reservations[id];if(confirm('Delete '+old.name+' · '+old.date+' '+old.time+'? You can restore it using Undo Delete for 3 days (72 hours).'))try{await this.changeReservation(id,old,(current,at)=>({...current,status:'deleted',statusBeforeDelete:current.status||'scheduled',deletedAt:at,updatedAt:at}));this.toast('RESERVATION DELETED · UNDO AVAILABLE FOR 72 HOURS');}catch(e){this.toast(e.message);}});};if(!this.reservationWatching){this.reservationWatching=true;this.watch(this.connection.ref.child('reservations'),snap=>{this.reservations=snap.val()||{};this.onReservationsChange?.();this.drawReservations?.();});}this.drawReservations=render;document.getElementById('guestBookingLink').onclick=()=>this.openGuestBookingLink();document.getElementById('undoReservationDelete').onclick=()=>this.openReservationUndo();document.getElementById('reservationsFromDate').onclick=()=>{fromDate=true;showUpcoming=false;render();};document.getElementById('resDate').onchange=()=>{fromDate=false;showUpcoming=false;render();};document.getElementById('enableReservationAlerts').onclick=()=>this.enableReservationAlerts();document.getElementById('upcomingReservations').onclick=()=>{fromDate=false;showUpcoming=true;render();};render();const validateGuests=()=>{const n=Number(document.getElementById('resPeople').value);document.getElementById('saveReservation').disabled=!Number.isInteger(n)||n<6||n>120;};document.getElementById('resPeople').oninput=validateGuests;validateGuests();document.getElementById('reservationForm').onsubmit=async event=>{event.preventDefault();try{const form=document.getElementById('reservationForm'),id=form.dataset.editId||'res_'+this.connection.now()+'_'+HostCore.uid();form.dataset.editId=id;const value={date:document.getElementById('resDate').value,name:document.getElementById('resName').value.trim(),time:document.getElementById('resTime').value,people:Number(document.getElementById('resPeople').value),phone:document.getElementById('resPhone').value.trim(),email:document.getElementById('resEmail').value.trim(),note:document.getElementById('resNote').value.trim(),table:document.getElementById('resTable').value,at:this.connection.now()};if(!value.date||!value.name||!value.time||!Number.isInteger(value.people)||value.people<6||value.people>120)throw Error('Complete the reservation fields. Minimum 6 guests.');if(document.getElementById('resSmsConsent').checked){const phone=ReservationFlow.phone(value.phone);if(!phone)throw Error('Enter a valid US phone number for SMS.');value.smsConsent={phone,at:value.at,textVersion:'reservation-sms-v2',source:'host-attested'};}await this.changeReservation(id,null,()=>value);form.reset();delete form.dataset.editId;document.getElementById('resPeople').value=6;this.toast('RESERVATION SAVED');}catch(e){this.toast(e.message);}};}
 close(){this.unsubs.forEach(fn=>fn());clearInterval(this.presenceTimer);clearInterval(this.reservationAlertTimer);clearTimeout(this.recordTimer);if(this.recorder?.state==='recording')this.recorder.stop();if(this.call)void this.endCall();void this.presence.remove();}
}
root.HostCommunications=HostCommunications;
})(globalThis);

